INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('abdominal','Abdominal','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"abdominal","name":"Abdominal","team":"townsfolk","ability":"Good Townsfolk know you''re the Abdominal. Evil wins at dusk if you''re dead. You are sober & healthy. [Minimum 1 Outsider per evil]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Abdominal (SCP-007) has a world revolving in his abdomen, and thus the world revolves around him.","summaryBullets":["All Townsfolk have knowledge of who the Abdominal is. This doesn''t apply to Outsiders or the rare good Minion.","This does not apply evil Townsfolk however.","If the Abdominal is dead, the good team will lose come dusk unless they can win before then.","This must occur, considering the Abdominal can never be drunk or poisoned."],"howToRun":["While setting up the game, before putting character tokens in the bag, replace Townsfolk character tokens with Outsider character tokens until number of Outsiders equal the number of starting evil players {{i|(or do nothing if it already equals or outnumbers it.)}}","During the first night, wake a good Townsfolk. Show them the **THIS PLAYER IS** info token, then the Abdominal token, then point at the Abdominal player. Put the Townsfolk to sleep. Repeat this for each good Townsfolk.","At dusk, if the Abdominal is dead, declare that the game ends and evil wins."],"quote":"I just woke up one day, and there it was. I don''t have any idea how it got there.","iconBy":"le_nuberto","jinxes":[{"name":"Boffin","align":"evil","text":"If the Demon has the Abdominal''s ability, the Abdominal''s ability cannot end the game for 3 days.","id":"boffin"},{"name":"Mezepheles","align":"evil","text":"If a Townsfolk becomes evil, their ability cannot end the game for 3 days.","id":"mezepheles"},{"name":"Pit-Hag","align":"evil","text":"A Pit-Hag can not create an Abdominal.","id":"pithag"},{"name":"Spy","align":"evil","text":"The 1st time the Spy sees the Grimoire, the Abdominal''s ability cannot end the game for 3 days.","id":"spy"},{"name":"Widow","align":"evil","text":"Once the Widow sees the Grimoire, the Abdominal''s ability cannot end the game for 3 days.","id":"widow"},{"name":"Shadoo","align":"evil","text":"Once the Shadoo sees the Grimoire, the Abdominal''s ability cannot end the game for 3 days.","slug":"shadoo"},{"name":"▼","align":"evil","text":"The 1st time the Spy sees the Grimoire, the Abdominal''s ability cannot end the game for 3 days.","slug":"scp-1936"},{"name":"Esper","align":"evil","text":"The 1st time the Esper sees the Grimoire, the Abdominal''s ability cannot end the game for 3 days.","id":"esper_the_bootleggers_anthology"},{"name":"Huli Jing","align":"evil","text":"The Huli-Jing cannot choose to have the Abdominal''s ability.","id":"hulijing_the_bootleggers_anthology"},{"name":"Tiresias","align":"good","text":"The 1st time the Tiresias sees the Grimoire, the Abdominal''s ability cannot end the game for 3 days.","id":"tiresias_circus_music"},{"name":"Actor","align":"good","text":"Only 1 jinxed character can be in-play.","id":"actor_festival_of_lanterns"},{"name":"Bloodless","align":"evil","text":"Once the Bloodless sees the Grimoire, the Abdominal''s ability cannot end the game for 2 days.","id":"bloodless_darkartists_stuff"}],"customBoxes":[{"title":"In the almanac JSON","content":"**Ability:** Good Townsfolk know you are the Abdominal. Evil wins at dusk if you''re dead. You are sober & healthy. [+1 Outsider]"},{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use the older version of the Abdominal, where it was an Outsider that wanted to hide at all times, even when dead, use this JSON. This is not practical to run unless you are with an expert friend group who can handle the potential shock of 1 good player possibly never claiming, ever.\n\nIf the Abdominal would die whilst already dead, declare that the game ends and their team loses.\n\n**Abdominal █~** (Outsider)\nIf you would be killed whilst already dead, your team loses.\n\n**Credit:** Ability: @lumiousgaming226. Image: @le_nuberto\n\n**Jinxes:**\nLeviathan: If the Leviathan nominates a dead Abdominal, the Abdominal''s team loses.\nRiot: During the Riot day, Riot players can freely nominate dead players. If the Riot nominates a dead Abdominal, the Abdominal''s team loses.\nSpy: If the Spy is (or has been) in play, the Abdominal is poisoned.\nWidow: If the Widow is (or has been) in play, the Abdominal is poisoned.\nMatsuraid: Only 1 jinxed character can be in play.\nAu’Wre: Only 1 jinxed character can be in play.\nEsper: If the Esper is (or has been) in play, the Abdominal is poisoned.\nKetos: If the Ketos correctly guesses a dead Abdominal, the Abdominal''s team loses.\nSeer: If the Seer is (or has been) in play, the Abdominal is poisoned.\nSchai: If the Shadoo is (or has been) in play, the Abdominal is poisoned."}],"firstNight":18.007,"otherNight":0,"reminders":["Doomsday"],"setup":true,"firstNightReminder":"One at a time, wake each good Townsfolk, show them the ''This character selected you'' card, show the Abdominal token and point to the Abdominal player.","art":"art/abdominal.png","jsonId":"abdominal_scp_fragmented_veil","curata":false}','scp-fragmented-veil/abdominal','published',datetime('now'),datetime('now')),
('ball-o-death','Ball o'' Death','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"ball-o-death","name":"Ball o'' Death","team":"townsfolk","ability":"Twice per game, at night*, choose a player: the 1st Townsfolk, Outsider, & Minion who choose them with their ability before you next wake die then.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Ball o'' Death (SCP-018) is a rubber ball that increases it''s bounciness efficiency for each bounce. However, the velocity of the bounces within it''s space can prove fatal.","summaryBullets":["Twice per game at night, the Ball o'' Death can throw itself towards a player. The 1st of each character type that gets too close to your mark via selecting them with their ability will be hit by the ball.","The Demon cannot be killed this way.","Players hit the ball don''t die immediately, but instead die from their injuries once the Ball o'' Death next wakes."],"howToRun":["Each night except the first, remove any **BALLIN''** reminder on any player marked with it, and all players with the **BOING!** reminder {{i|die}} - replace their **BOING!** reminder with the **DEAD** reminder, then wake the Ball o'' Death. They either shake their head no or point at any player. Put the Ball o'' Death to sleep.","If the Ball o'' Death chose a player, mark them with the **BALLIN''** reminder. **The Ball o'' Death loses an ability charge** - mark them with either the **1 USE** reminder, or if they already have that reminder, the **NO ABILITY** reminder and remove their night token from the night sheet {{i|(The Ball o'' Death won''t wake again.)}}","At any time, if a player chooses to use their ability on a player with the **BALLIN''** reminder and there isn''t a player of the same character type marked with the **BOING!** reminder, mark them with the **BOING!** reminder."],"quote":"All staff are reminded again to not ‘play’ with Ball o'' Death. There are disastrous consequences both during and after that action. -Scientific Director “Hex”","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run","content":"If you want to get a little bit bouncy and be able to kill EVERYONE with this character, use this JSON. This isn''t recommended unless your group loves chaos and is fine with seeing the Demon die anti-climatically during the night.\n\nEach night except the first, remove any **BALLIN''** reminder on any player marked with it, and all players with the **BOING!** reminder {{i|die}} - replace their **BOING!** reminder with the **DEAD** reminder, then wake the Ball o'' Death. They either shake their head no or point at any player. Put the Ball o'' Death to sleep.\n\nIf the Ball o'' Death chose a player, mark them with the **BALLIN''** reminder. **The Ball o'' Death loses an ability charge** - mark them with either the **1 USE** reminder, or if they already have that reminder, the **NO ABILITY** reminder and remove their night token from the night sheet {{i|(The Ball o'' Death won''t wake again.)}}\n\nAt any time, if a player chooses to use their ability on a player with the **BALLIN''** reminder, mark them with the **BOING!** reminder.\n\n**Ball o'' Death █+** (Townsfolk)\nTwice per game, at night*, choose a player: players who choose them with their ability before you next wake die then.\n\n**Other nights:** All marked players die. If the Ball o'' Death has not yet fully used their ability: Ball o'' Death either shows the ''no'' head signal, or points to a player. All other players choosing them with an ability are marked to die when you next wake.\n**Reminders:** Ballin'', Boing!, Boing!, Boing!, 1 use, Ability used, Dead, Dead, Dead\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":54.018,"reminders":["Ballin''","Boing!","Boing!","Boing!","1 use","Ability used","Dead","Dead","Dead"],"setup":false,"otherNightReminder":"All marked players die. If the Ball o'' Death has not yet fully used their ability: Ball o'' Death either shows the ''no'' head signal, or points to a player. The 1st Townsfolk, Outsider, & Minion choosing them with an ability are marked to die when you next wake.","art":"art/ball-o-death.png","jsonId":"ballodeath_scp_fragmented_veil","curata":false}','scp-fragmented-veil/ball-o-death','published',datetime('now'),datetime('now')),
('contestant','Contestant','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"contestant","name":"Contestant","team":"townsfolk","ability":"Once per day*, the Storyteller''s narrations will subtly contain a hint (arbitrary without this ability.) ","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-024 is a gameshow that will may supplement the game and it''s contestants with useful hints to win big!!!","summaryBullets":["When the Storyteller publicly speaks, listen wisely; their words may contain a divination into the past, present, or future amongst their words.","Between each dusk, the Storyteller is obligated to subtly give a hint once per day through their narration towards the gamestate.","This does not occur on the 1st night or day.","This could during basic game events, such as dawn, dusk, and execution, or even through public consultations or public abilities.","Everyone knows what is said when the Storyteller publicly speaks, so when it occurs, other players besides the Contestant may also pick up on the hint.","The Storyteller may still be elaborate and intricate in their narrations as need be, whether or not the Contestant is present.","If the Contestant is not in-play, or their ability isn''t functioning {{i|(drunkenness or poisoning)}}, the Storyteller may choose to provide a faulty hint about a true or false game scenario."],"howToRun":["During the first night, place the **HINTED** reminder on the Contestant {{i|(no hints can be provided on the 1st night or day)}}","After each dusk, remove the **HINTED** reminder on the Contestant.","Once per day, you must provide a hint towards the gamestate in your narrations or public declarations before the end of the next dusk. Once you do, mark the Contestant with the **HINTED** reminder."],"quote":"Contestants, are you ready? No? Begone then!","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"While setting up the game, before deciding on what character tokens to put in the bag, publicly announce what the Contestant''s █ variable will be for this game. This should be a standard unchanging number, write down the number on a piece of paper or on a phone.\n\nOnce per day, if the Contestant requests a private chat with you, take them away from the circle so you cannot be overheard. Whisper them a question, and the possible answers {{i|(or answer format)}} they can respond with. {{i|(If you cannot think of a question straight away, either take your time or ask them to come back in a few minutes.)}} If the Contestant answers incorrectly, **they lose a lifeline** - place or replace any of the **WRONG**, **WRONG 2 TIMES**, or **WRONG 3 TIMES** reminder tokens to add up to the number of answers they''ve answered incorrectly. If those reminder tokens add up to the Contestant''s █ variable, instead, remove them and mark their character token with the **DEAD** reminder. Tonight, the Contestant **dies**.\n\n**Contestant █~** (Townsfolk)\nEach day, visit the Storyteller to learn a question & answer it: the █th (and +) time you are wrong, you die tonight. [█ is known before setup]\n\n**Other nights:** If the Contestant answered incorrectly their █th time (which is publicly revealed before the tokens are finalized and put into the bag) today (or higher): the Contestant dies.\n**Reminders:** Wrong, Wrong 2 times, Wrong 3 times, Dead\n**Setup:** yes\n**Credit:** Ability: @le_nuberto. Image: @le_nuberto. Help: @supergdpwyl"}],"firstNight":0,"otherNight":0,"reminders":["Hinted"],"setup":false,"art":"art/contestant.png","jsonId":"contestant_scp_fragmented_veil","curata":false}','scp-fragmented-veil/contestant','published',datetime('now'),datetime('now')),
('living-drawing','Living Drawing','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"living-drawing","name":"Living Drawing","team":"townsfolk","ability":"Once per game, draw your ability (you learn what it is). Minions sees this drawing & if 1 publicly guesses what your ability does, your team loses.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Living Drawing (SCP-085) is a hand-drawn being that can interact with the images they are located in.","summaryBullets":["Once per game, during the day, the Living Drawing may come to the Storyteller to draw a new ability in fruition.","After the drawing is made, the Storyteller decides what the Living Drawing’s ability is. It may be the same ability as another character in Blood On The Clocktower, something similar, or something original.","The Living Drawing directly knows what their ability is once they draw it.","The Living Drawing may wake at any time during the night to learn information or to choose a player, or their ability may be passive - not requiring action from the player.","The upcoming night, once the Living Drawing has made their ability, Minions see this drawing directly.","If 1 then guesses what this ability is doing, then the Living Drawing''s team loses.","The guess must be public, and is shared between all Minions."],"howToRun":["During any day, the Living Drawing can request a private chat with you. Take them away from the circle so you cannot be overheard. They will draw their ability on a piece of paper. Afterwards, decide what ability the Living Drawing has - write it on a piece of paper or on a phone, and show them. During the game, treat that player as if they had that ability, waking them when needed, prompting them to choose players when needed, or whatever else is appropriate. Use the Living Drawing’s **?** reminders if you need to. Additionally, mark them with the **ART COMMISSIONED** reminder token.","At night, if the Living Drawing is marked with the **ART COMMISSIONED** reminder token, remove it and wake each Minion. Show the Living Drawing''s drawing. Put each Minion to sleep.","At any time during the game, if a Minion publicly guesses what the Living Drawing''s ability is and is incorrect, mark the Living Drawing with the **GUESS USED** reminder. Future guesses by Minion players have no effect.","At any time during the game, if a Minion publicly guesses what the Living Drawing''s ability is doing {{i|(or they are relatively close to this)}}, the game ends. Declare that the evil team wins."],"tips":["You can make the Living Drawing’s ability slightly better than a normal Townsfolk’s ability. Not having the ability to fully share it lest they lose the game to a Minion''s guess, the player will need to work harder to reap its full benefit for its team.","Generally, if a Minion makes a guess that is completely accurate on the Living Drawing''s effects, but not when they are occurring {{i|(''Each night'', ''Each day'', ''If a player was executed today'', etc.)}}, that is generally close enough to be considered a valid correct guess."],"quote":"𖨆","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON","content":"If you want the Living Drawing to not a possible lose condition on their team at the cost of having a less stronger ability, use this JSON. This is recommended if your group doesn''t prefer win-condition effects, especially on top of a Townsfolk.\n\n**Living Drawing █+** (Townsfolk)\nOnce per game, draw your ability (you learn what it is).\n\n**Other nights:** If the Living Drawing''s ability causes them to wake tonight: Wake the Living Drawing and run their ability.\n**Reminders:** ?, ?, ?\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":65.085,"reminders":["Art commissioned","Guess used","?","?","?"],"setup":false,"otherNightReminder":"If the Living Drawing made their ability today: Wake all Minions, show them the ''This character selected you'' card, the Living Drawing''s token, and their drawing. If the Living Drawing''s ability causes them to wake tonight: Wake the Living Drawing and run their ability.","art":"art/living-drawing.png","jsonId":"livingdrawing_scp_fragmented_veil","curata":false}','scp-fragmented-veil/living-drawing','published',datetime('now'),datetime('now'));
